package main
import("net/http";"crypto/tls";"crypto/x509";"encoding/json";"os";"fmt";"strconv";"time";"sync";"io";"strings";"errors";"net")
func main(){a:=os.Args;base:=a[1];if base!="http://127.0.0.1:18762"&&base!="https://127.0.0.1:18763"{panic("loopback only")};delay,size,fault,keep,rounds:=a[2],a[3],a[4],a[5],a[6];n,_:=strconv.Atoi(rounds);sizeN,_:=strconv.Atoi(size);roots:=x509.NewCertPool();pem,_:=os.ReadFile("ca.pem");if !roots.AppendCertsFromPEM(pem){panic("CA")};tr:=&http.Transport{DisableKeepAlives:keep=="0",MaxConnsPerHost:8,MaxIdleConnsPerHost:8,DisableCompression:true,TLSClientConfig:&tls.Config{RootCAs:roots,MinVersion:tls.VersionTLS12}};client:=&http.Client{Transport:tr,Timeout:time.Second,CheckRedirect:func(r *http.Request,v []*http.Request)error{return http.ErrUseLastResponse}};start:=time.Now();samples:=[]float64{};call:=func(i int)string{r,e:=client.Get(fmt.Sprintf("%s/?delay=%s&size=%s&fault=%s&id=%d",base,delay,size,fault,i));if e!=nil{var ne net.Error;if errors.As(e,&ne)&&ne.Timeout(){return "timeout"};return "network"};defer r.Body.Close();b,e:=io.ReadAll(r.Body);if e!=nil{return "network"};if r.StatusCode!=200{return strconv.Itoa(r.StatusCode)};var v struct{Ok bool;Data string};if json.Unmarshal(b,&v)!=nil||!v.Ok||len(v.Data)!=sizeN{return "invalid"};return "ok"};for k:=0;k<n;k++{t:=time.Now();out:=make([]string,25);for j:=0;j<25;j+=8{var wg sync.WaitGroup;for i:=j;i<j+8&&i<25;i++{wg.Add(1);go func(i int){defer wg.Done();out[i]=call(i)}(i)};wg.Wait()};for i,v:=range out{expected:="ok";if fault=="1"&&i<4{expected=[]string{"503","429","timeout","invalid"}[i]};if v!=expected{panic(fmt.Sprintf("case %d: %s != %s",i,v,expected))}};samples=append(samples,float64(time.Since(t).Microseconds())/1000)};b,_:=os.ReadFile("/proc/self/status");m:=map[string]any{"samples":samples,"elapsed_ms":float64(time.Since(start).Microseconds())/1000};for _,l:=range strings.Split(string(b),"\n"){f:=strings.Fields(l);if len(f)>1&&(f[0]=="VmHWM:"||f[0]=="VmRSS:"){v,_:=strconv.Atoi(f[1]);m[strings.TrimSuffix(f[0],":")]=v}};json.NewEncoder(os.Stdout).Encode(m)}
